(() => {
  const out = {};
  const q = (sel) => document.querySelector(sel);
  const f = (name) => { const e = Array.from(document.querySelectorAll('[data-field-name="'+name+'"]')).find(x=>x.closest('[class*="detail"], aside, [id*="details"]')||true); return e ? e.innerText.trim().replace(/\s+/g,' ') : null; };
  out.subject = (q('.subject-header .inline-edit, #work-package-description-header')||{}).innerText || (document.title||'');
  ['assignee','status','type','dueDate','combinedDate'].forEach(n => out[n] = f(n));
  const desc = q('.op-uc-container, .wiki-content, [data-field-name="description"]');
  out.description = desc ? desc.innerText.trim() : null;
  const comments = Array.from(document.querySelectorAll('.op-uc-p')).map(e=>e.innerText.trim()).filter(t=>t.includes('vop2v-n1'));
  out.comment_hits = comments;
  return out;
})()

(() => {
  const pane = document.querySelector('[id*="work-package-details"], aside[class*="details"], .work-packages--details') || document;
  const labels = Array.from(pane.querySelectorAll('.wp-replacement-label')).map(s => {
    const kv = s.closest('.attributes-key-value') || s.parentElement;
    return (s.innerText.trim() + ' :: ' + (kv? kv.innerText.replace(/\n/g,' | ').trim() : ''));
  });
  const hdr = (pane.innerText||'').slice(0,400);
  return {labels: labels.slice(0,40), hdr};
})()

(() => {
  const out = {};
  const pane = document.querySelector('.work-packages--details, aside');
  const all = (pane||document).innerText;
  out.pane_head = all.slice(0,700);
  const g = (name) => { const els = Array.from((pane||document).querySelectorAll('[data-field-name="'+name+'"]')); return els.map(e=>({label:e.getAttribute('aria-label'), txt:e.innerText.replace(/\s+/g,' ').trim()})); };
  out.assignee = g('assignee');
  out.status = g('status');
  out.combinedDate = g('combinedDate');
  const desc = (pane||document).querySelector('[data-field-name="description"], .op-uc-container');
  out.description = desc ? desc.innerText.trim() : null;
  return out;
})()

(() => {
  const rows = Array.from(document.querySelectorAll('table tbody tr')).map(tr => {
    const subj = tr.querySelector('[data-field-name="subject"] button, td:nth-child(3) button');
    const id = tr.querySelector('td:nth-child(2) a');
    return {id: id ? id.textContent.trim() : null, subject: subj ? subj.textContent.trim() : null};
  });
  const foot = document.querySelector('table tfoot') || Array.from(document.querySelectorAll('*')).find(e=>/\(1 - \d+\/\d+\)/.test(e.textContent||'') && e.children.length<4);
  const viewTitle = document.querySelector('h2');
  return {rows, foot: foot ? foot.innerText.trim() : null, view: viewTitle ? viewTitle.innerText.trim() : null, url: location.href};
})()
